namespace AkyildizKargoEtiket;

/// <summary>
/// Catering micro koli etiketinin logosu — akyildiz-logo-dikey-siyah.svg (çatı okları + "AKYILDIZ" + "LOJİSTİK"),
/// Barlow Condensed Bold, 112 x 84 dot, 1 bit. ZPL ^GFA verisi (satır başına 14 bayt).
/// Üretim (12.11.2026): AkyildizSevkiyat tools/depo-etiket ile aynı yöntem — 8x süper örnekleme, eşik 140.
/// 58 dot'ta "LOJİSTİK" termal baskıda okunmuyordu; 84 dot seçildi.
/// </summary>
internal static class CateringKoliLogo
{
    public const int Width = 112;
    public const int Height = 84;
    public const int BytesPerRow = 14;
    public const int TotalBytes = 1176;
    public const string Hex = "";

    /// <summary>Logoyu (x, y) noktasına basan ZPL alanı.</summary>
    public static string Zpl(int x, int y) => $"^FO{x},{y}^GFA,{TotalBytes},{TotalBytes},{BytesPerRow},{Hex}^FS\n";
}